#include "BrakePedalMonitor.h"

#include <stddef.h>

bool BrakePedalMonitor_Update(uint8_t position, bool *input_valid, bool *brake_applied)
{
    if ((input_valid == NULL) || (brake_applied == NULL)) {
        return false;
    }

    if (position > 100U) {
        *input_valid = false;
        *brake_applied = false;
        return false;
    }

    *input_valid = true;
    *brake_applied = (position >= 5U);
    return true;
}
